/* Screen templates. Events and persistence are in app.js. */
(() => {
const M=window.Studio,A=window.Art,icon=A.icon;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,act,cls='primary',extra='')=>`<button class="btn ${cls}" data-action="${act}" ${extra}>${text}</button>`;
const ib=(name,act,label,extra='')=>`<button class="icon-btn" data-action="${act}" aria-label="${label}" ${extra}>${icon(name)}</button>`;
const tag=t=>`<span class="tag">${t}</span>`,art=w=>A.object(w);
const date=v=>new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const row=(title,sub,act,extra='')=>`<button class="list-row" data-action="${act}" ${extra}><span><strong>${esc(title)}</strong><small>${esc(sub)}</small></span>${icon('chevron',18)}</button>`;
const empty=(title,desc)=>`<div class="empty"><span class="empty-mark">${icon('layers',34)}</span><h2>${title}</h2><p>${desc}</p>${btn('去共创，选一件物品','home')}</div>`;
function nav(p){return ['discover','points','mine'].map((id,i)=>`<button data-action="navigate" data-page="${id}" aria-current="${p===id?'page':'false'}">${icon(['layers','award','user'][i],21)}<span>${['共创','积分','我的'][i]}</span></button>`).join('');}
function header(c){if(c.page==='editor')return `${ib('back','back','返回来源页')}<div class="header-center"><strong>创作工作台</strong><span id="save-status" role="status">${c.saveLabel}</span></div>${btn('退出','exit','text')}`;if(['discover','points','mine'].includes(c.page))return `<a class="brand" href="#discover"><span class="brand-symbol" aria-hidden="true"><i></i><i></i><i></i></span><span>物之再生<small>RE:BORN · INDUSTRIAL ARCHIVE</small></span></a>${btn('关于','about','header-note')}`;return `${ib('back','back','返回')}<strong class="header-center">${c.page==='detail'?'物件档案':'我的数字作品'}</strong>${c.page==='detail'?'':tag('本地')}`;}
function detail(c){const i=c.item;return `<section class="page-content"><span class="eyebrow">OBJECT / ${String(M.items.indexOf(i)+1).padStart(3,'0')}</span><h1>${i.name}</h1><p class="lede">${i.subtitle}</p><div class="detail-art">${A.object({itemId:i.id},true)}</div><div class="definition"><span>类别</span><strong>${M.category(i.category).name} · 示意画布</strong><span>素材性质</span><strong>本原型自绘 SVG</strong><span>馆藏对应</span><strong>来源、年代待核实</strong></div><p class="body-copy">${i.description}</p><p class="notice">这是一份创作练习素材，并非已获馆方授权的藏品复制图，也不代表生产确认。</p>${btn('用这件物品开始创作','start','primary full')}${btn(c.s.favorites.includes(i.id)?'已收藏 · 取消收藏':'收藏这件物品','favorite','secondary full')}</section>`;}
function slider(label,key,value,min,max,unit=''){return `<label class="range-field"><span>${label}<output data-output="${key}">${value}${unit}</output></span><input type="range" data-field="${key}" aria-label="${label}" min="${min}" max="${max}" value="${value}"></label>`;}
function tools(c){const d=c.d;if(c.tool==='compose')return `<div class="range-grid">${slider('缩放','scale',d.scale,40,160,'%')}${slider('旋转','rotation',d.rotation,-180,180,'°')}${slider('水平位置','x',d.x,-60,60)}${slider('垂直位置','y',d.y,-60,60)}</div><p class="tool-help">移动、缩放与替换均可撤销。边缘外的图案会被裁切。</p>`;if(c.tool==='material')return `<p class="tool-label">器物底色</p><div class="swatches">${A.palette.map(p=>`<button data-action="color" data-id="${p.id}" aria-pressed="${d.color===p.id}" style="--swatch:${p.color}"><i></i>${p.name}</button>`).join('')}</div>${d.category==='enamel'?`<div class="segmented">${btn('搪瓷杯','canvas','',`data-id="cup" aria-pressed="${d.canvas==='cup'}"`)}${btn('搪瓷盘','canvas','',`data-id="plate" aria-pressed="${d.canvas==='plate'}"`)}</div>`:'<p class="tool-help">保留物件原有比例，在中心画布自由安排图案。</p>'}`;return `<div class="motif-strip">${M.items.filter(i=>i.category===d.category).map(i=>`<button data-action="replace" data-id="${i.id}" aria-pressed="${!d.imageId&&i.id===d.itemId}">${A.panel(i.pattern)}<span>${i.name}</span></button>`).join('')}</div>${btn(icon('upload',16)+' 上传／替换个人图像','upload','text full')}${d.imageId?`<span class="image-name">正在使用：${esc(d.imageName)}</span>`:''}`;}
function editor(c){const d=c.d;if(!d)return empty('没有正在编辑的草稿','选择一件物品，开始新的设计。');return `<section class="editor-screen"><div class="editor-meta"><span>${M.category(d.category).name} / ${esc(d.title||'未命名草稿')}</span><div>${ib('undo','undo','撤销',d.past.length?'':'disabled')}${ib('redo','redo','重做',d.future.length?'':'disabled')}${ib('rotate','reset','重置构图')}</div></div><div class="canvas-stage" id="canvas-stage"><div id="work-preview">${art(d)}</div><span class="canvas-note">数字设计示意 · 拖动图案调整位置</span>${btn('换物件','swap','canvas-change')}</div><div class="editor-tools"><div class="tool-tabs" role="tablist" aria-label="编辑工具">${[['compose','构图','move'],['material','器物','palette'],['motif','纹样','layers']].map(([id,label,ic])=>`<button role="tab" data-action="tool" data-id="${id}" aria-selected="${id===c.tool}">${icon(ic,17)}${label}</button>`).join('')}</div><div class="tool-panel" role="tabpanel" aria-label="编辑工具">${tools(c)}</div></div><div class="editor-footer">${btn('大图预览','preview','secondary')}${btn('保存作品 '+icon('arrow',18),'finish')}</div></section>`;}
function result(c){const w=c.w;if(!w)return empty('这件作品暂时找不到','可能已被删除，可返回“我的”查看其他记录。');const sub=c.s.submissions.find(x=>x.workId===w.id);return `<section class="page-content result-screen"><div class="result-heading">${tag('已保存到此浏览器')}<h1>${esc(w.title)}</h1><p>${M.category(w.category).name} · ${date(w.savedAt||w.createdAt)}</p></div><div class="result-art">${art(w)}</div>${w.idea?`<p class="work-idea">${esc(w.idea)}</p>`:''}<div class="two-actions">${btn(sub?'编辑为新副本':'继续编辑','edit-work','secondary',`data-id="${w.id}"`)}${btn('我的作品','mine')}</div>${btn('返回共创','home','text full')}<div class="optional-block"><div><span class="eyebrow">下一步 · 可选</span><h2>${sub?'已留存演示投稿':'让创作被看见'}</h2><p>${sub?'仅保存在本机，未发送馆方。':'先保存，再决定是否参与投稿。'}</p></div>${btn(sub?'查看状态':'演示投稿',sub?'submission':'submit','secondary',`data-id="${sub?.id||w.id}"`)}</div><p class="footer-note">数字设计不代表可直接制作。实体化仍需版权、馆方与工艺审核。</p></section>`;}
function points(c){const entries=[...c.s.ledger].reverse(),total=entries.reduce((n,x)=>n+x.points,0);return `<section class="page-content points-screen"><div class="page-title"><span class="eyebrow">GROWTH / 创作足迹</span><h1>每次创作，都有回响</h1></div><div class="points-hero"><span>我的演示积分</span><strong>${total}<small>分</small></strong><div><span>${c.s.works.length} 件作品 · ${c.s.submissions.length} 次演示投稿</span>${btn('积分规则','rules','text')}</div></div><p class="notice">仅为本地演示记录，不是馆方账户，也不代表正式文化权益。</p>${row('文化权益说明','展示、署名与实体化等正式权益均待馆方确认','rights')}<div class="section-heading"><h2>成长时间线</h2><span>${entries.length} 条记录</span></div>${entries.length?`<ol class="timeline">${entries.map(e=>`<li><div class="timeline-dot"></div><div><span class="eyebrow">${date(e.createdAt)}</span><h3>${e.label}</h3><p>${esc(e.title)}</p><small>来源 ${esc(e.sourceId.slice(-8))}</small></div><strong>+${e.points}</strong></li>`).join('')}</ol>`:empty('第一条记录，从创作开始','完成一件数字作品，即可看到可追溯的成长记录。')}</section>`;}
function mini(w,kind,publication){
 const sketch=kind==='drafts'&&w.inputTab==='sketch'&&w.lastWorkspace!=='editor';
 const thumb=sketch?window.Inspiration?.sketchThumbnail(w):'';
 const title=esc(w.title||(sketch&&w.sketchSubject?.trim())||(sketch?'手绘草稿':'未命名草稿'));
 const status=kind==='drafts'?'草稿':publication?btn('私有原稿 · 已在本机广场展示 ›','gallery-detail','text work-publication-link',`data-id="${esc(publication.id)}"`):'完成作品 · 私有';
 return `<article class="work-card"><button class="work-cover" data-action="${kind==='drafts'?'resume':'view-work'}" data-id="${w.id}" aria-label="${kind==='drafts'?'继续编辑':'查看'}${title}">${thumb?`<img class="saved-vessel-preview" src="${esc(thumb)}" alt="">`:art(w)}</button><div class="work-card-body"><span class="work-card-status">${status}</span><h3>${title}</h3><p>${M.category(w.category).name} · ${date(w.updatedAt||w.savedAt)}</p><div>${btn(kind==='drafts'?'继续编辑':'查看作品',kind==='drafts'?'resume':'view-work','text',`data-id="${w.id}"`)}${ib('trash','delete','删除'+(kind==='drafts'?'草稿':'作品'),`data-id="${w.id}" data-kind="${kind}"`)}</div></div></article>`;}
function workPick(w,ids){
 const title=w.title||'未命名作品',vessel=window.Vessels?.data[w.canvas]?.name;
 const split=title.lastIndexOf('·');
 const displayName=split>0&&title.slice(split+1).trim()===vessel?title.slice(0,split).trim():title;
 return `<label class="work-card work-pick"><span class="work-cover" aria-hidden="true">${art(w)}</span><span class="work-pick-copy"><strong>${esc(displayName||title)}</strong><small>${esc(vessel||M.category(w.category).name)} · ${date(w.updatedAt||w.savedAt)}</small></span><input type="checkbox" data-work-pick value="${esc(w.id)}" aria-label="选择作品：${esc(title)}" ${ids.has(w.id)?'checked':''}></label>`;
}
function mine(c){const pubSaved=(c.s.galleryCollections||[]).filter(id=>M.findPublication(c.s,id));const f=c.s.ui.filter||'works',counts=[c.s.works.length,c.s.drafts.length,c.s.submissions.length,c.s.favorites.length+pubSaved.length];let list='';if(f==='works'||f==='drafts')list=c.s[f].length?`<div class="work-grid${c.selectedWorkIds?' work-selection-grid':''}">${[...c.s[f]].reverse().map(w=>f==='works'&&c.selectedWorkIds?workPick(w,c.selectedWorkIds):mini(w,f,f==='works'&&c.s.publications?.find(p=>p.workId===w.id&&p.state==='published'))).join('')}</div>`:empty(f==='drafts'?'还没有草稿':'还没有作品',f==='drafts'?'进行中的创作会出现在这里。':'从「共创」选择一件器物开始。');if(f==='submissions')list=c.s.submissions.length?c.s.submissions.slice().reverse().map(x=>row(x.snapshot.title,x.status+' · '+date(x.createdAt),'submission',`data-id="${x.id}"`)).join(''):empty('还没有演示投稿','先保存作品，再按自己的意愿参与。');if(f==='favorites')list=c.s.favorites.length?c.s.favorites.map(id=>{const i=M.getItem(id);return `<button class="catalog-row" data-action="choose" data-id="${i.id}">${A.object({itemId:i.id},true)}<span><strong>${i.name}</strong><small>${M.category(i.category).name} · 原创示意</small></span>${icon('arrow',18)}</button>`;}).join(''):empty('还没有收藏','在首页或物件详情点击收藏，方便下次找回。');if(f==='favorites'&&pubSaved.length){if(!c.s.favorites.length)list='';list+='<div class="section-heading"><h2>收藏的广场作品</h2></div>'+window.Views.savedGallery(c);}return `<section class="page-content mine-screen"><div class="my-tabs" role="group" aria-label="作品分组">${[['works','作品'],['drafts','草稿'],['submissions','投稿'],['favorites','收藏']].map(([id,label],i)=>btn(`${label} <small>${counts[i]}</small>`,'filter','',`data-id="${id}" aria-pressed="${f===id}"`)).join('')}</div>${list}<div class="ai-settings-row"${c.selectedWorkIds?' hidden':''}>${btn('作品迁移','archive-transfer','text full')}${btn('AI 连接设置','ai-connection','text full')}</div><details class="archive-disclosure"${c.selectedWorkIds?' hidden':''}><summary>作品存储说明</summary><p>作品默认私有，保存在当前浏览器。清除网站数据会删除记录。</p></details></section>`;}
function catalog(mode){return M.categories.map(cat=>`<div class="catalog-section"><h3>${cat.name}<small>${cat.en}</small></h3>${M.items.filter(i=>i.category===cat.id).map(i=>`<button class="catalog-row" data-action="${mode==='swap'?'swap-select':'choose'}" data-id="${i.id}">${A.object({itemId:i.id},true)}<span><strong>${i.name}</strong><small>自绘示意 · ${cat.name}</small></span>${icon('arrow',18)}</button>`).join('')}</div>`).join('');}
function searchResults(q){const found=M.search(q);return !q.trim()?'<p class="search-empty">描述一种图案、颜色或物件，开始查找。</p>':found.length?found.map(i=>`<button class="catalog-row" data-action="choose" data-id="${i.id}">${A.object({itemId:i.id},true)}<span><strong>${i.name}</strong><small>${i.subtitle}</small></span>${icon('arrow',18)}</button>`).join(''):`<div class="search-empty"><h3>暂时没找到匹配物件</h3><p>试试“牡丹”“喜鹊”“邮票”或“糖纸”。</p>${btn('浏览全部物件','browse','secondary')}</div>`;}
window.Views={esc,btn,ib,icon,tag,date,row,empty,art,nav,header,detail,editor,tools,result,points,mine,catalog,searchResults};
})();
